void ClipLaserBeams(LASER *plaser)
{
    for (int ibeam = 0; ibeam < plaser->cbeam; ibeam++) {
        BEAM *pbeam = &plaser->abeam[ibeam];
        QW apos[2];
        float sLength;
        GetLaserBeamPoints(plaser, pbeam, apos, &sLength);
        if (pbeam->pmqFirst == 0) {
            float sFull = sLength;
            pbeam->sClipped = sFull;
            pbeam->sFull = sFull;
        } else {
            MQ *pmqNearest = 0;
            float sNearest = sLength;
            for (MQ *pmq = pbeam->pmqFirst; pmq != 0; pmq = pmq->pmqNext) {
                if (pmq->s < sNearest) {
                    sNearest = pmq->s;
                    pmqNearest = pmq;
                }
            }
            WKR wkr;
            memset(&wkr, 0, 0x60);
            wkr.psoSource = plaser;
            wkr.ppartSource = (void *)pmqNearest->aside[0].plo;
            wkr.ploTarget = (LO *)pmqNearest->aside[1].pgeom;
            wkr.grftak = 0x1000;
            wkr.damage = -10;
            wkr.pos = pmqNearest->aside[0].pos;
            PaloAbsorbWkr(&wkr);
            pbeam->sClipped = sNearest;
        }
    }
}

